package litmus

import (
	"fmt"
	"strings"
	"testing"
)

const openAPIHeader = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */
`

func TestIsUIFileExcludesGeneratedHeaders(t *testing.T) {
	for _, header := range []string{
		openAPIHeader,
		"// @GeNeRaTeD\n",
		"// DO NOT EDIT\n",
		"// AUTO-GENERATED\n",
		"// autogenerated\n",
		"// This file was generated\n",
		"\n\n\n\n// do not edit\n",
	} {
		if isUIFile("frontend/src/api/schema.ts", strings.Split(header+"const settingEnabled = true;", "\n")) {
			t.Errorf("generated file counted as UI: %q", header)
		}
	}
	for _, content := range []string{
		"export function Panel() { return <div />; }",
		"\n\n\n\n\n// DO NOT EDIT is outside the header\n",
	} {
		if !isUIFile("frontend/src/api/Panel.tsx", strings.Split(content, "\n")) {
			t.Errorf("handwritten file excluded from UI: %q", content)
		}
	}
}

func TestGateNotesExcludeGeneratedSourcesAndDefinitions(t *testing.T) {
	const schema, panel = "frontend/src/api/schema.ts", "frontend/src/api/Panel.tsx"
	tree := mapTree{
		schema:              openAPIHeader + "const unrelatedEnabled = true;\nconst settingEnabled = true;\n",
		panel:               "const settingEnabled = false;\n",
		"backend/config.go": "// Code generated by configgen. DO NOT EDIT.\nvar settingEnabled = true\n",
	}
	notes := gateNotes(tree, []string{schema, panel})
	if !strings.Contains(notes, "### settingEnabled") || !strings.Contains(notes, panel) {
		t.Fatalf("handwritten gate missing:\n%s", notes)
	}
	for _, unwanted := range []string{schema, "backend/config.go", "unrelatedEnabled"} {
		if strings.Contains(notes, unwanted) {
			t.Errorf("generated source leaked into gate scan: %q\n%s", unwanted, notes)
		}
	}
}

func TestGitTreePreservesHeaderLineNumbers(t *testing.T) {
	svc, _ := newSvc(t)
	const path = "frontend/src/api/Panel.tsx"
	content := "\n\n\n\n\n// DO NOT EDIT is outside the header\nexport function Panel() { return <div />; }\n"
	svc.runner.(*fakeRunner).gitOut["show "+head6394+":"+path] = content
	tree := &gitTree{s: svc, ctx: ctx, dir: t.TempDir(), sha: head6394, files: map[string][]string{}}
	lines := tree.file(path)
	if tree.err != nil {
		t.Fatal(tree.err)
	}
	if got := strings.Join(lines, "\n"); got != content {
		t.Fatalf("PR-head content changed: %q", got)
	}
	if !isUIFile(path, lines) {
		t.Fatal("marker after line five counted as a generated header")
	}
}

func TestIntakeClassifiesUIFromPRHeadHeaders(t *testing.T) {
	const schema = "frontend/src/api/schema.ts"
	for _, other := range []string{"backend/config.go", "frontend/src/api/Panel.tsx"} {
		t.Run(other, func(t *testing.T) {
			svc, _ := newSvc(t)
			f := svc.runner.(*fakeRunner)
			f.gitOut["diff --name-status"] = "M\x00" + schema + "\x00M\x00" + other + "\x00"
			f.gitOut["diff --numstat"] = "1\t1\t" + schema + "\x001\t1\t" + other + "\x00"
			// The changed hunk does not include the generated header.
			f.gitOut["diff --patch"] = fmt.Sprintf("diff --git a/%[1]s b/%[1]s\n--- a/%[1]s\n+++ b/%[1]s\n@@ -100 +100 @@\n-unrelatedEnabled: false;\n+unrelatedEnabled: true;\n", schema)
			f.gitOut["show "+head6394+":"+schema] = openAPIHeader + "const unrelatedEnabled = true;\n"
			f.gitOut["show "+head6394+":"+other] = "const settingEnabled = true;\n"
			f.gitOut["grep -n"] = head6394 + ":" + schema + ":5:const unrelatedEnabled = true;\n" + head6394 + ":" + other + ":1:const settingEnabled = true;\n"

			run, err := svc.Intake(ctx, "s1", prURL)
			if err != nil {
				t.Fatal(err)
			}
			if len(run.Gaps) != 0 {
				t.Fatalf("intake gaps: %q", run.Gaps)
			}
			pack := readRunFile(t, svc, run, "context-pack.md")
			wantUI := strings.HasSuffix(other, ".tsx")
			if strings.Contains(pack, "## How the touched features are gated") != wantUI {
				t.Errorf("gate notes mismatch, want UI = %t:\n%s", wantUI, pack)
			}
			if strings.Contains(pack, "### unrelatedEnabled") || wantUI && !strings.Contains(pack, "### settingEnabled") {
				t.Errorf("gate scan included generated flags or lost the handwritten gate:\n%s", pack)
			}
			if n := f.count("show " + head6394 + ":" + schema); n != 1 {
				t.Errorf("generated header read %d times, want one cached PR-head read", n)
			}
		})
	}
}
